class Solution {
  public int maxDistinctElements(int[] nums, int k) {
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    long prev = Long.MIN_VALUE / 2;
    int count = 0;
    for (int x : sorted) {
      // smallest value this element can take that is still above the previous choice
      long candidate = Math.max(prev + 1, (long) x - k);
      if (candidate <= (long) x + k) {
        count++;
        prev = candidate;
      }
    }
    return count;
  }
}
